prompt --application/shared_components/logic/application_processes/set_language
begin
wwv_flow_imp_shared.create_flow_process(
 p_id=>wwv_flow_imp.id(98122126631896255)
,p_process_sequence=>1
,p_process_point=>'AFTER_LOGIN'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'SET_LANGUAGE'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    IF :P_LANG = ''ar'' THEN',
'        APEX_UTIL.SET_SESSION_LANG( ''ar'');  ',
'    ELSE',
'        :P_LANG := ''en'';',
'        APEX_UTIL.SET_SESSION_LANG( ''en'');  ',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_version_scn=>1
);
end;
