,p_attribute_03=>'APP_USER_SECURITY.VALID_USER'
,p_attribute_05=>'N'
,p_plsql_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'FUNCTION CHECK_PRIVILEGE',
'RETURN BOOLEAN',
'AS',
'BEGIN',
