,p_name=>'Change Theme'
,p_event_sequence=>10
,p_triggering_element_type=>'BUTTON'
,p_triggering_button_id=>wwv_flow_imp.id(101000837206562360)
,p_bind_type=>'live'
,p_execution_type=>'IMMEDIATE'
,p_bind_event_type=>'click'
);
wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(101000980551562362)
,p_event_id=>wwv_flow_imp.id(101000950535562361)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_name=>'Change Theme'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'const body = document.querySelector(''body'');',
'const icon = document.querySelector(''button#changeTheme span'');',
'const moon = ''fa-moon-o'';',
'const sun  = ''fa-sun-o'';',
'',
'// Trigger The Functions',
'changeTheme();',
'',
'// Change Theme Function',
'function changeTheme() {',
'    body.classList.toggle(''dark-theme'');',
'    changeIcon();',
'}',
'',
'// Change Icon Function',
'function changeIcon() {',
'    if (icon.classList.contains(moon)) {',
'        icon.classList.remove(moon)',
'        icon.classList.add(sun)',
'    } else {',
'        icon.classList.remove(sun)',
'        icon.classList.add(moon)',
'    }',
'}'))
);
end;
