wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(61075289060568825)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Upload Main Image'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_file_names        APEX_T_VARCHAR2;',
'    l_file              APEX_APPLICATION_TEMP_FILES%ROWTYPE;',
'    l_file_name         VARCHAR2(255);',
'    l_request_url	    VARCHAR2(32767);',
'    l_result	        CLOB;',
'    l_request_filename	VARCHAR2(500);',
'    l_inner_folder  	VARCHAR2(500);',
'BEGIN',
'    l_file_names := apex_string.SPLIT (',
'                        p_str => :P1_MAIN_IMAGE,',
'                        p_sep => '':'' );',
'',
'    IF l_file_names.count = 0 THEN',
unistr('        RAISE_APPLICATION_ERROR(-20001, ''\064A\062C\0628 \0639\0644\064A\0643 \0631\0641\0639 \0627\0644\0631\0626\064A\0633\064A\0629 \0644\0644\0645\0646\062A\062C!'');'),
'    END IF;',
'',
'    SELECT *',
'      INTO l_file',
'      FROM APEX_APPLICATION_TEMP_FILES',
'     WHERE NAME = :P1_MAIN_IMAGE;',
'',
'    l_file_name := TO_CHAR(get_current_date, ''YY'') ',
'                        || DBMS_RANDOM.STRING(''x'', 8)',
'                        || SYSTEM_CONTROLS.file_extension_by_mimetype(p_mimetype => l_file.MIME_TYPE);',
'',
'    l_request_url := :G_OCI_BASE_URL||''/b/sellers/o/''||l_file_name;',
'    ',
'    l_result := APEX_WEB_SERVICE.make_rest_request (',
'                    p_url                  => l_request_url,',
'                    p_http_method          => ''PUT'',',
'                    p_body_blob            => l_file.BLOB_CONTENT,',
'                    p_credential_static_id => ''OCI_AUTH''',
'                );',
'',
'    IF APEX_WEB_SERVICE.g_status_code NOT IN ( 200, 201, 202, 203, 204, 205, 206, 207, 226 ) THEN',
'        SYSTEM_CONTROLS.ERROR_LOGS ( p_error_type    => ''SYSTEM_ERROR'',',
'                                             p_process_name  => ''OCI_OS.put_object_P1 - App: '' || :APP_ID,',
'                                             p_error_code    => -2,',
'                                             p_error_message => SUBSTR(l_result, 1, 4000),',
'                                             p_logger_name   => :APP_USER',
'                                        );',
'        RAISE_APPLICATION_ERROR(-20001, ''Error with uploading Data!'');',
'    END IF;',
'',
'    :P1_MAIN_IMAGE_URL := l_request_url;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>44830348071420156
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(61075682078568825)
,p_process_sequence=>40
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Upload Product Images'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_file_names        APEX_T_VARCHAR2;',
'    l_file              APEX_APPLICATION_TEMP_FILES%ROWTYPE;',
'    l_file_name         VARCHAR2(255);',
'    l_request_url	    VARCHAR2(32767);',
'    l_result	        CLOB;',
'    l_request_filename	VARCHAR2(500);',
'    l_inner_folder  	VARCHAR2(500);',
'BEGIN',
'    l_file_names := apex_string.SPLIT (',
'                        p_str => :P1_MAIN_IMAGE,',
'                        p_sep => '':'' );',
'',
'    -- IF l_file_names.count = 0 THEN',
unistr('    --     RAISE_APPLICATION_ERROR(-20001, ''\064A\062C\0628 \0639\0644\064A\0643 \0631\0641\0639 \0635\0648\0631 \0627\0644\0645\0646\062A\062C!'');'),
'    -- END IF;',
'',
'    IF l_file_names.count > 1 THEN                    ',
'        FOR i IN 1 .. l_file_names.count LOOP',
'            SELECT *',
'              INTO l_file',
'              FROM APEX_APPLICATION_TEMP_FILES',
'             WHERE NAME = l_file_names(i);',
'',
'            l_file_name := TO_CHAR(get_current_date, ''YY'') ',
'                                || DBMS_RANDOM.STRING(''x'', 8)',
'                                || SYSTEM_CONTROLS.file_extension_by_mimetype(p_mimetype => l_file.MIME_TYPE);',
'',
'            l_request_url := :G_OCI_BASE_URL||''/b/sellers/o/''||l_file_name;',
'',
'            l_result := APEX_WEB_SERVICE.make_rest_request (',
'                            p_url                  => l_request_url,',
'                            p_http_method          => ''PUT'',',
'                            p_body_blob            => l_file.BLOB_CONTENT,',
'                            p_credential_static_id => ''OCI_AUTH''',
'                        );',
'',
'            IF APEX_WEB_SERVICE.g_status_code NOT IN ( 200, 201, 202, 203, 204, 205, 206, 207, 226 ) THEN',
'                SYSTEM_CONTROLS.ERROR_LOGS ( p_error_type    => ''SYSTEM_ERROR'',',
'                                             p_process_name  => ''OCI_OS.put_object_P1 - App: '' || :APP_ID,',
'                                             p_error_code    => -2,',
'                                             p_error_message => SUBSTR(l_result, 1, 4000),',
'                                             p_logger_name   => :APP_USER',
'                                        );',
'                RAISE_APPLICATION_ERROR(-20002, ''Error with uploading Data!'');',
'            END IF;',
'',
'            INSERT INTO PRODUCT_IMAGES ( PRODUCT_ID, URL, FILE_NAME, MIME_TYPE, SEQ )',
'                VALUES ( PRODUCTS_SEQ.nextval, l_request_url, l_file.FILENAME, l_file.MIME_TYPE, i );',
'            ',
'            IF SQL%ROWCOUNT = 0 THEN',
unistr('                RAISE_APPLICATION_ERROR(-20003, ''\062E\0637\0623 \0641\064A \0631\0641\0639 \0635\0648\0631 \0627\0644\0645\0646\062A\062C!'');'),
'            END IF;',
'        END LOOP;',
'    ELSE',
'        SELECT *',
'          INTO l_file',
'          FROM APEX_APPLICATION_TEMP_FILES',
'         WHERE NAME = :P1_MAIN_IMAGE;',
'',
'        l_file_name := TO_CHAR(get_current_date, ''YY'') ',
'                            || DBMS_RANDOM.STRING(''x'', 8)',
'                            || SYSTEM_CONTROLS.file_extension_by_mimetype(p_mimetype => l_file.MIME_TYPE);',
'',
'        l_request_url := :G_OCI_BASE_URL||''/b/sellers/o/''||l_file_name;',
'        ',
'        l_result := APEX_WEB_SERVICE.make_rest_request (',
'                        p_url                  => l_request_url,',
'                        p_http_method          => ''PUT'',',
'                        p_body_blob            => l_file.BLOB_CONTENT,',
'                        p_credential_static_id => ''OCI_AUTH''',
'                    );',
'',
'        IF APEX_WEB_SERVICE.g_status_code NOT IN ( 200, 201, 202, 203, 204, 205, 206, 207, 226 ) THEN',
'            SYSTEM_CONTROLS.ERROR_LOGS ( p_error_type    => ''SYSTEM_ERROR'',',
'                                             p_process_name  => ''OCI_OS.put_object_P1 - App: '' || :APP_ID,',
'                                             p_error_code    => -2,',
'                                             p_error_message => SUBSTR(l_result, 1, 4000),',
'                                             p_logger_name   => :APP_USER',
'                                        );',
'            RAISE_APPLICATION_ERROR(-20004, ''Error with uploading Data!'');',
'        END IF;',
'',
'        :P1_MAIN_IMAGE_URL := l_request_url;',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'P1_PRODUCT_IMAGES'
,p_process_when_type=>'ITEM_IS_NOT_NULL'
,p_internal_uid=>44830741089420156
);
