begin
wwv_flow_imp_page.create_page(
 p_id=>23
,p_name=>'Product details'
,p_alias=>'PRODUCT-DETAILS'
,p_step_title=>'Product details'
,p_warn_on_unsaved_changes=>'N'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code_onload=>wwv_flow_string.join(wwv_flow_t_varchar2(
'const slideImgs = [...document.querySelectorAll(''.slider_container img'')];',
'const slidesCount = slideImgs.length;',
'let currentSlide = 1;',
'',
'const previous = document.getElementById(''previous'');',
'const next = document.getElementById(''next'');',
'const indicator = document.getElementById(''indicator'');',
'const slideNumber = document.getElementById(''slide_number'');',
'',
'if(slidesCount > 0){',
'// Handle Previous and Next Click',
'previous.addEventListener(''click'', prevSlide);',
'next.addEventListener(''click'', nextSlide);',
'',
'// Create Indicator Ul',
'const paginationElement = document.createElement(''ul'');',
'paginationElement.setAttribute(''class'', ''indicator_list flex'')',
'paginationElement.setAttribute(''id'', ''pagination-ul'')',
'',
'// Create Li base on Slides Count',
'for (let i = 1; i <= slidesCount; i++) {',
'  let paginationItem = document.createElement(''li'');',
'  paginationItem.setAttribute(''class'', ''indicator_item'');',
'  paginationItem.setAttribute(''data-index'', i);',
'  paginationItem.appendChild(document.createTextNode(i));',
'  ',
'  paginationElement.appendChild(paginationItem);',
'}',
'// Add Ul to The Page',
'indicator.appendChild(paginationElement);',
'',
'// Paginatoin UL',
'const paginationUl = document.getElementById(''pagination-ul'');',
'',
'// Paginatoin Li',
'const paginationLi = [...document.querySelectorAll(''.indicator_item'')];',
'',
'// Bullets Click',
'paginationLi.forEach(bullet => {',
'  bullet.addEventListener(''click'', () => {',
'    currentSlide = parseInt(bullet.getAttribute(''data-index''));',
'    checker();',
'  });',
'});',
'',
'// Trigger The Checker Function',
'checker();',
'',
'// Functions',
'function nextSlide() {',
'  if(next.classList.contains(''disabled'')) return;',
'  currentSlide++;',
'  checker();',
'}',
'function prevSlide() {',
'  if(previous.classList.contains(''disabled'')) return;',
'  currentSlide--;',
'  checker();',
'}',
'function checker() {',
'//   Set Slide Number ',
'  slideNumber.textContent = `Slide #${currentSlide} of ${slidesCount}`',
'  ',
'//   Remove Active Classes',
'  removeActive();',
'  ',
'//   Active Current Slide',
'  slideImgs[currentSlide - 1].classList.add(''active'');',
'  ',
'//   Active Slide Pagination Number',
'  paginationUl.children[currentSlide - 1].classList.add(''active'');',
'  ',
'//   Check if Current Silde is the Fisrt one',
'  currentSlide == 1 ',
'    ? previous.classList.add(''disabled'')',
'    : previous.classList.remove(''disabled'')',
'  ',
'//   Check if Current Silde is the Last one',
'  currentSlide == slidesCount ',
'    ? next.classList.add(''disabled'')',
'    : next.classList.remove(''disabled'')',
'}',
'',
'// Remove All Active Classes',
'function removeActive() {',
'//   Remove Image Active',
'  slideImgs.forEach(img => {',
'    img.classList.remove(''active'');',
'  });',
'  ',
'//   Remove Pagination Active',
'  paginationLi.forEach(bullet => {',
'    bullet.classList.remove(''active'');',
'  });',
'}',
'}'))
,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
'*,',
'*::before,',
'*::after {',
'  margin: 0;',
'  padding: 0;',
'  box-sizing: border-box;',
'}',
'ul {',
'  list-style: none;',
'}',
'/* a {',
'  text-decoration: none;',
'} */',
'img {',
'  max-width: 120%;',
'  max-height: 120%;',
'}',
'.flex {',
'  display: flex;',
'  flex-direction: row;',
'  flex-wrap: wrap;',
'  align-items: center',
'  /* align-items: center; */',
' } ',
'',
'.slider_container {',
'  width: 100%;',
'  height: 250px;',
'  position: relative;',
'}',
'.slider_container img {',
'  width: 800px;',
'  max-height: 250px;',
'  position: absolute;',
'  opacity: 0;',
'  transition: opacity 1s;',
'  z-index: 1;',
'  outline: 1px solid',
'}',
'.slider_container img.active {',
'  opacity: 1;',
'}',
'.slide_number {',
'  position: absolute;',
'  left: 1150px;',
'  top: 10px;',
'  background-color: rgba(0 0 0 / 60%);',
'  color: #FFF;',
'  padding: 5px 10px;',
'  font-size: 15px;',
'  border-radius: 6px;',
'  z-index: 2;',
'}',
'.slider_controls {',
'  width: 100%;',
'  /* margin: auto; */',
'  margin-top: auto;',
'  justify-content: space-between;',
'}',
'.previous,',
'.next {',
'  background-color: hsl(174deg 100% 29%);',
'  color: #FFF;',
'  font-size: 16px;',
'  text-align: center;',
'  cursor: pointer;',
'  user-select: none;',
'  padding: 5px 15px;',
'  border-radius: 4px;',
'  transition: 0.3s;',
'}',
'.previous:hover,',
'.next:hover {',
'  background-color: #009688cc;',
'}',
'.previous.disabled,',
'.next.disabled {',
'  background-color: hsl(174deg 100% 29% / 50%);',
'  cursor: no-drop;',
'}',
'.indicator {',
'  display: block;',
'}',
'.indicator_list {',
'  gap: 0.5rem;',
'}',
'.indicator_item {',
'  background-color: #bbb;',
'  padding: 5px 10px;',
'  border-radius: 4px;',
'  color: #FFF;',
'  font-weight: 700;',
'  cursor: pointer;',
'}',
'.indicator_item.active {',
'  background-color: #009688;',
'}'))
,p_page_template_options=>'#DEFAULT#'
,p_required_role=>'MUST_NOT_BE_PUBLIC_USER'
,p_protection_level=>'C'
,p_page_component_map=>'02'
);
