wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(201625678662896695)
,p_plug_name=>unistr('\062A\0641\0627\0635\064A\0644 \0627\0644\0645\0646\062A\062C')
,p_parent_plug_id=>wwv_flow_imp.id(200753402020166699)
,p_region_template_options=>'#DEFAULT#:t-Region--removeHeader js-removeLandmark:t-Region--scrollBody'
,p_plug_template=>wwv_flow_imp.id(97052300333387632)
,p_plug_display_sequence=>2
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT p.ID,',
'       p.SELLER_ID,',
'       p.TYPE_ID,',
'       p.NAME_AR,',
'       p.VIDEO_URL,',
'    --    ''<iframe src="'' || p.VIDEO_URL ||''" width="100" height="80"></iframe>'' video,',
'       p.CITY_ID,',
'       p.DESCRIPTION_AR,',
'       p.ADDRESS_AR,',
'       p.MAIN_IMAGE_URL,',
'       p.MAP_URL,',
'       SUBSTR(p.MAP_URL, INSTR(p.MAP_URL, ''src="'') + 5, INSTR(p.MAP_URL, ''width'') - 16) AS FRAME_SRC,',
'       p.REFERENCE_NO,',
'       p.CATEGORY_ID,',
'       ------------------',
'       r.INSTRUMENT_NO,',
'       r.NEIGHBOURHOODS_ID,',
'       r.STREET_NAME_AR,',
'       r.PROPERTY_TYPE_ID,',
'       r.THERE_MORTGAGE_AR,',
'       r.INFORMATION_THAT_AFFECT_PROPERTY_AR,',
'       r.RIGHTS_AND_OBLIGATIONS_AR,',
'       r.USAGE_ID,',
'       r.FACADE_ID,',
'       r.ADVERTISER_ID,',
'       r.AD_TYPE_ID,',
'       r.AD_SUB_TYPE_ID,',
'       r.SPACE,',
'       r.STREET_WIDTH,',
'       r.CONSTRUCTION_DATE,',
'       r.IS_THERE_MORTGAGE,',
'       r.IS_RIGHTS_AND_OBLIGATIONS,',
'       r.IS_INFORMATION_THAT_AFFECT_PROPERTY,',
'       ------------------',
'       c.VEHICLE_MAKE_ID,',
'       c.VEHICLE_MODEL_ID,',
'       c.VEHICHLE_CATEGORY,',
'       c.YEAR,',
'       c.VEHICLE_EXTERNAL_COLOR_ID,',
'       c.TRANSMISSION_ID,',
'       c.FUEL_TYPE_ID,',
'       c.ODO_METER,',
'       c.CHASSIS_NUMBER,',
'       c.PLATE_NUMBER,',
'       c.SERIAL_NUMBER,',
'       c.IS_THERE_DOCUMENT,',
'       c.IS_THERE_INSPECTION,',
'       c.INSPECTION_URL,',
'       c.DOCUMENT_URL',
'    --    c.IS_DROWNED,',
'    --    c.DROWING_INFO,',
'    --    c.DROWING_FILE_URL,',
'    --    c.IS_BURNED,',
'    --    c.BURN_INFO,',
'    --    c.BURN_FILE_URL,',
'    --    c.IS_ACCIDENT,',
'    --    c.ACCIDENT_INFO,',
'    --    c.ACCIDENT_FILE_URL',
'       ------------------',
'  FROM PRODUCTS p,',
'       REAL_STATE_DETAILS r,',
'       CAR_DETAILS c',
' WHERE p.ID = r.PRODUCT_ID (+)',
'   AND p.ID = c.PRODUCT_ID (+)',
'   AND SELLER_ID = :P_SELLER_ID;'))
,p_is_editable=>true
,p_edit_operations=>'i:u:d'
,p_lost_update_check_type=>'VALUES'
,p_plug_source_type=>'NATIVE_FORM'
,p_ajax_items_to_submit=>'P23_SELLER_ID'
);
